import sys
import math
import random
from collections import defaultdict

def get_random_address():
    p = bytearray(random.getrandbits(8) for _ in range(8))
    return int.from_bytes(p, byteorder='little')

class HashSplitter:
    @staticmethod
    def splitmix64(x):
        x = (x + 0x9e3779b97f4a7c15) & 0xFFFFFFFFFFFFFFFF
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9 & 0xFFFFFFFFFFFFFFFF
        x = (x ^ (x >> 27)) * 0x94d049bb133111eb & 0xFFFFFFFFFFFFFFFF
        return x ^ (x >> 31)

    def __call__(self, x):
        seed = self.splitmix64(int(random.getrandbits(64)) ^ get_random_address() | 1)
        return self.splitmix64(x ^ seed)

MOD_CONST = 10**9 + 7

class Modular:
    def __init__(self, v=0):
        v = v % MOD_CONST
        self.value = v

    @staticmethod
    def extended_gcd(a, m):
        if m == 0:
            return a, 1, 0
        g, y, x = Modular.extended_gcd(m, a % m)
        y -= (a // m) * x
        return g, x, y

    @staticmethod
    def modular_inverse(a, m=MOD_CONST):
        g, x, _ = Modular.extended_gcd(a, m)
        return x % m

    def __iadd__(self, other):
        self.value += other.value
        if self.value >= MOD_CONST:
            self.value -= MOD_CONST
        return self

    def __isub__(self, other):
        self.value -= other.value
        if self.value < 0:
            self.value += MOD_CONST
        return self

    def __imul__(self, other):
        self.value = (self.value * other.value) % MOD_CONST
        return self

    def __itruediv__(self, other):
        inv = Modular.modular_inverse(other.value)
        self.value = (self.value * inv) % MOD_CONST
        return self

    def __add__(self, other):
        res = Modular(self.value)
        res += other
        return res

    def __sub__(self, other):
        res = Modular(self.value)
        res -= other
        return res

    def __mul__(self, other):
        res = Modular(self.value)
        res *= other
        return res

    def __truediv__(self, other):
        res = Modular(self.value)
        res /= other
        return res

    def pow(self, p):
        assert p >= 0
        res = Modular(1)
        base = Modular(self.value)
        while p > 0:
            if p & 1:
                res *= base
            base *= base
            p >>= 1
        return res

def main():
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    prob = [[Modular(int(data[1 + i * N + j])) / Modular(100) for j in range(N)] for i in range(N)]
    index = 1 + N * N

    masks_by_count = [[] for _ in range(N + 1)]
    lookup_mask = [-1] * (1 << N)
    for mask in range(1 << N):
        c = bin(mask).count('1')
        lookup_mask[mask] = len(masks_by_count[c])
        masks_by_count[c].append(mask)

    possible_states = dict()
    initial_mask = 1 << lookup_mask[0]
    possible_states[initial_mask] = Modular(1)

    for left in range(N):
        new_states = dict()
        product_mask = [Modular(1) for _ in range(1 << N)]
        for current_mask in range(1 << N):
            for col in range(N):
                p = prob[left][col]
                if (current_mask & (1 << col)) != 0:
                    product_mask[current_mask] *= p
                else:
                    product_mask[current_mask] *= (Modular(1) - p)

        new_bits = [0] * N
        new_possible = [Modular(0) for _ in range(1 << N)]

        for state_mask, prob_state in possible_states.items():
            for i in range(N):
                new_bits[i] = 0
            for m in masks_by_count[left]:
                if ((state_mask >> lookup_mask[m]) & 1) != 0:
                    for i in range(N):
                        if ((m >> i) & 1) == 0:
                            new_bits[i] |= 1 << lookup_mask[m | (1 << i)]
            for current_mask in range(1, 1 << N):
                ctz = (current_mask & -current_mask).bit_length() - 1
                new_possible[current_mask] = new_possible[current_mask & (current_mask - 1)] + Modular(new_bits[ctz])
                combined_mask = new_possible[current_mask]
                new_states[combined_mask] = new_states.get(combined_mask, Modular(0)) + prob_state * product_mask[current_mask]
        possible_states = new_states

    answer = Modular(0)
    last_mask_bit = (1 << N) - 1
    for state_mask, val in possible_states.items():
        if ((state_mask >> lookup_mask[last_mask_bit]) & 1) != 0:
            answer += val
    print(int(answer))

if __name__ == "__main__":
    main()

